// Given: mapping between world space (metres, y up) and canvas pixels (y down).
// Do not edit this file.
import type { Vec2 } from "../math/vec2";

export type View = {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  /** World point shown at the centre of the canvas. */
  center: Vec2;
  /** Zoom: CSS pixels per metre. */
  pixelsPerMetre: number;
};

export type ViewOptions = { center?: Vec2; pixelsPerMetre?: number };

export function createView(canvas: HTMLCanvasElement, options: ViewOptions = {}): View {
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Canvas 2D is not available in this browser");
  return {
    canvas,
    ctx,
    center: options.center ?? { x: 0, y: 0 },
    pixelsPerMetre: options.pixelsPerMetre ?? 50,
  };
}

/** Canvas size in CSS pixels. */
export function viewSize(view: View): { width: number; height: number } {
  return { width: view.canvas.clientWidth, height: view.canvas.clientHeight };
}

/**
 * Matches the canvas backing store to its displayed size and the screen's
 * pixel density, then sets the context so drawing uses CSS pixels.
 * Call once per frame before drawing; it is cheap when nothing changed.
 */
export function fitCanvas(view: View): void {
  const { canvas, ctx } = view;
  const dpr = window.devicePixelRatio || 1;
  const w = Math.max(1, Math.round(canvas.clientWidth * dpr));
  const h = Math.max(1, Math.round(canvas.clientHeight * dpr));
  if (canvas.width !== w || canvas.height !== h) {
    canvas.width = w;
    canvas.height = h;
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}

export function worldToScreen(view: View, p: Vec2): Vec2 {
  const { width, height } = viewSize(view);
  return {
    x: width / 2 + (p.x - view.center.x) * view.pixelsPerMetre,
    y: height / 2 - (p.y - view.center.y) * view.pixelsPerMetre,
  };
}

export function screenToWorld(view: View, p: Vec2): Vec2 {
  const { width, height } = viewSize(view);
  return {
    x: view.center.x + (p.x - width / 2) / view.pixelsPerMetre,
    y: view.center.y - (p.y - height / 2) / view.pixelsPerMetre,
  };
}

/** The world-space rectangle currently visible. */
export function visibleWorld(view: View): { min: Vec2; max: Vec2 } {
  const { width, height } = viewSize(view);
  const a = screenToWorld(view, { x: 0, y: height });
  const b = screenToWorld(view, { x: width, y: 0 });
  return { min: a, max: b };
}
